from typing import List

def autocomplete(partial_command: str) -> List[str]:
    completions = []
    defined_completions = {
        'artisan': ['make', 'migrate', 'serve', 'test', 'route', 'optimize', 'clear', 'down', 'up', 'list', 'tinker'],
    }
    aliases = {
        'artisan': 'php artisan',
    }

    for alias, command in aliases.items():
        if partial_command.startswith(alias):
            partial_command = partial_command.replace(alias, command)

