from typing import List, Tuple

def move_player(grid: List[str], x: int, y: int, direction: str) -> Tuple[int, int]:
    height = len(grid)
    width = len(grid[0])

    if direction == 'U' and x > 0 and grid[x-1][y] == '.':
        return x-1, y
    elif direction == 'D' and x < height-1 and grid[x+1][y] == '.':
        return x+1, y
    elif direction == 'L' and y > 0 and grid[x][y-1] == '.':
        return x, y-1
    elif direction == 'R' and y < width-1 and grid[x][y+1] == '.':
        return x, y+1
    else:
        return x, y
