public async send(amount: number, toAddressHash: string, fromAddressHash?: string): Promise<void> {
  if (this.STATE === WalletState.EMPTY) {
    throw new Error(`ElectraJs.Wallet: You can't #send() from an empty wallet (#state = "EMPTY").`);
  }

  if (this.LOCK_STATE === WalletLockState.LOCKED) {
    throw new Error(`ElectraJs.Wallet: Wallet is locked. Cannot send transactions.`);
  }

  // Retrieve unspent transactions based on fromAddressHash or default address
  const unspentTransactions = fromAddressHash
    ? this.getUnspentTransactions(fromAddressHash)
    : this.getUnspentTransactions(this.DEFAULT_ADDRESS_HASH);

  if (unspentTransactions.length === 0) {
    throw new Error(`ElectraJs.Wallet: No unspent transactions available for the specified address.`);
  }

  // Create and broadcast the new transaction
  const newTransaction = this.createTransaction(amount, toAddressHash, unspentTransactions[0]);
  this.broadcastTransaction(newTransaction);
}
