function createSelector<T, U>(
  inputSelectors: ((state: T) => any)[],
  transform: (...args: any[]) => U
): (state: T) => U {
  const memo: Map<string, U> = new Map();

  return (state: T) => {
    const args = inputSelectors.map(selector => selector(state));
    const key = JSON.stringify(args);

    if (memo.has(key)) {
      return memo.get(key)!;
    }

    const result = transform(...args);
    memo.set(key, result);
    return result;
  };
}
```

The `createSelector` function takes an array of input selectors and a transform function as arguments. It returns a memoized selector function that efficiently computes and caches the result based on the input selectors. Inside the memoized selector function, the values returned by the input selectors are computed and used as a key to cache the result. If the result for the given input selectors is already cached, it is returned directly from the cache. Otherwise, the transform function is called with the input selector values, and the result is cached before being returned.

