            return "Record created successfully"
        except Exception as e:
            return f"Error creating record: {str(e)}"

    def read_record(self, record_id):
        try:
            query = f"SELECT * FROM table_name WHERE id = {record_id}"
            result = self.client.query(query)
            if result:
                return result[0]  # Assuming only one record will be returned
            else:
                return "Record not found"
        except Exception as e:
            return f"Error reading record: {str(e)}"

    def update_record(self, record_id, name, age):
        try:
            query = f"UPDATE table_name SET name = '{name}', age = {age} WHERE id = {record_id}"
            self.client.execute(query)
            return "Record updated successfully"
        except Exception as e:
            return f"Error updating record: {str(e)}"

    def delete_record(self, record_id):
        try:
            query = f"DELETE FROM table_name WHERE id = {record_id}"
