struct Bank {
    accounts: std::collections::HashMap<u32, f64>,
    next_account_id: u32,
}

impl Bank {
    fn new() -> Bank {
        Bank {
            accounts: std::collections::HashMap::new(),
            next_account_id: 1,
        }
    }

    fn create_account(&mut self, initial_balance: f64) -> u32 {
        let account_id = self.next_account_id;
        self.accounts.insert(account_id, initial_balance);
        self.next_account_id += 1;
        account_id
    }

    fn deposit(&mut self, account_id: u32, amount: f64) -> Result<(), String> {
        if let Some(balance) = self.accounts.get_mut(&account_id) {
            *balance += amount;
            Ok(())
        } else {
            Err("Account does not exist".to_string())
        }
    }

    fn withdraw(&mut self, account_id: u32, amount: f64) -> Result<(), String> {
        if let Some(balance) = self.accounts.get_mut(&account_id) {
            if *balance >= amount {
                *balance -= amount;
                Ok(())
            } else {
                Err("Insufficient funds".to_string())
            }
        } else {
            Err("Account does not exist".to_string())
        }
    }

    fn check_balance(&self, account_id: u32) -> Result<f64, String> {
        if let Some(&balance) = self.accounts.get(&account_id) {
            Ok(balance)
        } else {
            Err("Account does not exist".to_string())
        }
    }
}

fn main() {
    let mut bank = Bank::new();
    let account1 = bank.create_account(100.0);
    let account2 = bank.create_account(50.0);

    println!("Account 1 balance: {:?}", bank.check_balance(account1)); // Output: Ok(100.0)
    println!("Account 2 balance: {:?}", bank.check_balance(account2)); // Output: Ok(50.0)

    bank.deposit(account1, 50.0).unwrap();
    bank.withdraw(account2, 20.0).unwrap();

    println!("Account 1 balance: {:?}", bank.check_balance(account1)); // Output: Ok(150.0)
    println!("Account 2 balance: {:?}", bank.check_balance(account2)); // Output: Ok(30.0)
}
