function validateGraphQLDocument(graphQLDocument) {
  const lines = graphQLDocument.split('\n');
  let typeSpecified = false;

  for (let line of lines) {
    const trimmedLine = line.trim();
    if (trimmedLine.startsWith('type')) {
      typeSpecified = true;
      break;
    }
  }

  if (!typeSpecified) {
