class HelpHandler(KeywordHandler):

    def help(self):
        self.respond(HELP_TEXT)

    def handle(self):
        topic = self.args[0].lower()
        if topic == 'stock':
            self.respond("Please send your receipts in the format "
                         "' <Commodity code> <stock on hand > . <quantity received>'")
