const fetchUserData = (jwt, callback) => {
  const allowPrivate = useSelector((state: AppState) => state.global.security.allowPrivate);
  const options = {
    enabled: Boolean(jwt),
  };

  if (allowPrivate) {
    if (options.enabled) {
      fetch('/api/user', {
        method: 'get',
      })
        .then(response => {
          if (response.ok) {
            return response.json();
          } else {
            throw new Error('Failed to retrieve user data');
          }
        })
        .then(userData => {
          callback(userData);
        })
        .catch(error => {
          console.error('Error retrieving user data:', error);
        });
    } else {
      console.log('User data retrieval is not enabled.');
    }
  } else {
    console.log('Private user data retrieval is not allowed.');
  }
};
