```typescript
class TabManager {
  description: IObservable<string | undefined>;
  hasWarning: IObservable<boolean | undefined>;
  private tabAppearance: boolean;

  constructor() {
    this.description = new Observable<string | undefined>();
    this.hasWarning = new Observable<boolean | undefined>();
    this.tabAppearance = false;
  }

  changeTabAppearance(hasWarning: boolean): void {
    this.tabAppearance = hasWarning;
    // Change tab appearance logic here
  }
}

class Observable<T> implements IObservable<T> {
  private observers: Array<(value: T) => void> = [];

  subscribe(observer: (value: T) => void): void {
    this.observers.push(observer);
  }

  unsubscribe(observer: (value: T) => void): void {
    this.observers = this.observers.filter((obs) => obs !== observer);
  }

  notify(value: T): void {
    this.observers.forEach((observer) => observer(value));
  }
}
```

