            index_delta = end[0] - start[0]
            percent = (target_index - start[0]) / index_delta
            value_delta = end[1] - start[1]

            return start[1] + value_delta * percent

    def to_array(self):
        result = []

        for (index, value) in self.data:
            result.append(index)
            result.append(value)

        return result

