from typing import List

def summaryRanges(nums: List[int]) -> List[str]:
    res = []
    if not nums:
        return res  # Return an empty list if input list is empty
    start = end = nums[0]
    for i in range(1, len(nums)):
        if nums[i] == end + 1:
            end = nums[i]
        else:
            if start == end:
                res.append(str(start))
            else:
                res.append(str(start) + "->" + str(end))
            start = end = nums[i]
    if start == end:
        res.append(str(start))
    else:
        res.append(str(start) + "->" + str(end))
    return res
```

