def generate_function_signature(parameters):
    signature = []
    for param in parameters:
        param_name, param_type, is_optional = param
        if is_optional:
            signature.append(f":param {param_name}: {param_type}, optional")
        else:
            signature.append(f":param {param_name}: {param_type}")
    return '\n'.join(signature)
