extension Publisher {
    func passthrough(_ closure: @escaping (Output) -> Void) -> AnyPublisher<Output, Failure> {
        return self.handleEvents(receiveOutput: { output in
            closure(output)
        }).eraseToAnyPublisher()
    }
}
