def json_loader(sortkeys):
    def _loader(line):
        if sortkeys:
            return json.loads(line)
        else:
            # if --no-sortkeys, let's preserve file order
            return json.JSONDecoder(object_pairs_hook=OrderedDict).decode(line)

    return _loader


