func isValidEmail(_ email: String) -> Bool {
    let emailComponents = email.components(separatedBy: "@")

    // Check if there is exactly one "@" symbol
    guard emailComponents.count == 2 else {
        return false
    }

    let username = emailComponents[0]
    let domain = emailComponents[1]

    // Check if "@" is not the first or last character
    guard username.first != "@" && username.last != "@" else {
        return false
    }

    // Check if there is at least one dot after the "@" symbol
    guard let dotIndex = domain.firstIndex(of: ".") else {
        return false
    }

    // Check if the characters before and after "@" do not contain spaces
    guard !username.contains(" ") && !domain.contains(" ") else {
        return false
    }

    // Check if the domain part consists of at least two characters
    guard domain[dotIndex..<domain.endIndex].count > 1 else {
        return false
    }

    return true
}
