type Property = {
    name: string;
    type: string;
};

function interfaceProperties(interfaceString: string): Property[] {
    const properties: Property[] = [];

    // Remove comments and whitespace from the interface string
    const cleanInterfaceString = interfaceString.replace(/\/\*.*?\*\//g, '').replace(/\s/g, '');

    // Extract property name and type using regular expressions
    const propertyRegex = /(\w+):(\w+\??);/g;
    let match;
    while ((match = propertyRegex.exec(cleanInterfaceString)) !== null) {
        const [, name, type] = match;
        properties.push({ name, type });
    }

    return properties;
}

// Example usage
