        sessionManager.requestInterceptor = ContentTypeInterceptor(acceptableContentTypes: contentTypes)
    }

    func GET(url: URLConvertible, parameters: Parameters? = nil, progress: ((Progress) -> Void)? = nil, success: ((DataResponse<Any, AFError>) -> Void)? = nil, failure: ((AFError) -> Void)? = nil) {
        sessionManager.request(url, method: .get, parameters: parameters)
            .validate()
            .downloadProgress(closure: { (prog) in
                progress?(prog)
            })
            .responseJSON { response in
                switch response.result {
                case .success:
                    success?(response)
                case .failure(let error):
                    failure?(error)
                }
            }
    }
}

class ContentTypeInterceptor: RequestInterceptor {
    let acceptableContentTypes: [String]

    init(acceptableContentTypes: [String]) {
        self.acceptableContentTypes = acceptableContentTypes
    }

    func adapt(_ urlRequest: URLRequest, for session: Session, completion: @escaping (Result<URLRequest, Error>) -> Void) {
        var urlRequest = urlRequest
        urlRequest.setValue(acceptableContentTypes.joined(separator: ","), forHTTPHeaderField: "Accept")
        completion(.success(urlRequest))
    }
}
