fn evaluate_rpn(expr: &str) -> i32 {
    let mut stack: Vec<i32> = Vec::new();
    for token in expr.split_whitespace() {
        match token {
            "+" => {
                let b = stack.pop().unwrap();
                let a = stack.pop().unwrap();
                stack.push(a + b);
            }
            "-" => {
                let b = stack.pop().unwrap();
                let a = stack.pop().unwrap();
                stack.push(a - b);
            }
            "*" => {
                let b = stack.pop().unwrap();
                let a = stack.pop().unwrap();
                stack.push(a * b);
            }
            "/" => {
                let b = stack.pop().unwrap();
                let a = stack.pop().unwrap();
                stack.push(a / b);
            }
            _ => {
                let num = token.parse().unwrap();
                stack.push(num);
            }
        }
    }
    stack.pop().unwrap()
}
