        return sum((t - p) ** 2 for t, p in zip(true, pred)) / len(true)

    errors = {
        8: mean_squared_error(orig_TS, F8),
        9: mean_squared_error(orig_TS, F9),
        10: mean_squared_error(orig_TS, F10),
