class HistoryManager:
    _history = []

    def __init__(self):
        self._ignoredups = False
        self._histappend = False
        self._prompt_command = ""

    def add_command(self, command):
        if self._ignoredups and command in self._history:
            return
        self._history.append(command)
        if self._histappend:
            with open('history.txt', 'a') as file:
                file.write(command + '\n')

    def get_history(self):
        if self._histappend:
            with open('history.txt', 'r') as file:
                file_history = file.readlines()
            return self._history + file_history
        else:
            return self._history

    def clear_history(self):
        self._history = []
        if self._histappend:
            open('history.txt', 'w').close()

    @property
    def ignoredups(self):
        return self._ignoredups

    @ignoredups.setter
    def ignoredups(self, value):
        self._ignoredups = value

    @property
    def histappend(self):
        return self._histappend

    @histappend.setter
