function countSuccessfulNodes(tree) {
  let count = tree.success ? 1 : 0; // Initialize count based on the root node's success property

  // Recursively traverse the tree and count successful nodes in each subtree
  for (const child of tree.children) {
    count += countSuccessfulNodes(child);
  }

  return count;
}

